	parsedURL, err := url.Parse(redirectPath)
	if err != nil {
		return "", err
	}

	// Only allow relative paths or paths on the trusted domain
	if parsedURL.Host != "" && parsedURL.Host != "yourapp.com" {
		return "", errors.New("untrusted redirect host")
	}

	// Prevent dangerous schemes like javascript: or data:
	if parsedURL.Scheme != "" && parsedURL.Scheme != "https" && parsedURL.Scheme != "http" {
		return "", errors.New("invalid redirect scheme")
	}

	// Create a copy of the OAuth config with the custom redirect URL
	config := *OAuthConfig
	config.RedirectURL = redirectPath

	// Generate the authorization URL
	authURL := config.AuthCodeURL(state)

	// Set the state in a cookie for later validation
	http.SetCookie(w, &http.Cookie{
		Name:     "oauth_state",
		Value:    state,
		HttpOnly: true,
		Secure:   true,
		SameSite: http.SameSiteLaxMode,
		Path:     "/",
	})

	return authURL, nil
